pub fn is_palindrome(s: &str) -> bool {
    let mut left = 0;
    let mut right = s.chars().count() - 1;
    while left < right {
        if !is_letter_digit(s.chars().nth(left).unwrap()) {
            left += 1;
        }
        if !is_letter_digit(s.chars().nth(right).unwrap()) {
            right -= 1;
        } else {
            if s.chars().nth(left).unwrap().to_lowercase().next().unwrap() != s.chars().nth(right).unwrap().to_lowercase().next().unwrap() {
                return false;
            }
            left += 1;
            right -= 1;
        }
    }
    true
}

fn is_letter_digit(c: char) -> bool {
    c.is_alphabetic() || c.is_digit(10)
}

