pub fn caesar(s: &str, shift: u8) -> String {
    let alphabet: char = if let Some(first) = s.chars().next() {
        first
    } else {
        'a'
    };
    let mut out = String::new();
    for c in s.chars() {
        let offset = if c.is_alphabetic() {
            if c.is_uppercase() {
                (c as u8 - alphabet as u8 + shift) % 26 + alphabet as u8
            } else {
                (c as u8 - alphabet as u8 + shift) % 26 + alphabet as u8
            }
        } else {
            c
        };
        out.push(c.to_ascii_uppercase() as char)
    }
    out
}

